// Turns new Drive files and webhook calls into { url, name } - one item per document.
// Drive files must be readable by link (see Setup). Folders and unsupported files are skipped.
const SUPPORTED = /\.(pdf|docx|pptx|xlsx|xls|epub|html?|png|jpe?g|webp|tiff?)$/i;
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.body && j.body.url) {            // Webhook: POST { "url": "https://...", "name": "optional" }
    const url = String(j.body.url).trim();
    out.push({ json: { url, name: j.body.name || url.split('/').pop().split('?')[0] } });
    continue;
  }
  if (!j.id || j.mimeType === 'application/vnd.google-apps.folder') continue;
  const googleNative = String(j.mimeType || '').startsWith('application/vnd.google-apps.');
  if (!googleNative && j.mimeType !== 'application/pdf' && !SUPPORTED.test(j.name || '')) continue;
  const native = { document: 'document', presentation: 'presentation', spreadsheet: 'spreadsheets' }[String(j.mimeType).split('.').pop()];
  if (googleNative && !native) continue;   // Drawings, forms etc.
  const url = native ? `https://docs.google.com/${native}/d/${j.id}/edit` : `https://drive.google.com/file/d/${j.id}/view`;
  out.push({ json: { url, name: j.name } });
}
return out;

